-- 479: Original BrillaPrep Cambridge A-Level Biology (9700) Metabolism: Respiration and Photosynthesis questions (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_479_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_479_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_metabolism_s2_001', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which gas is released when water molecules are split during the light-dependent reactions of photosynthesis?', 'multiple_choice', NULL, '["A. Oxygen","B. Carbon dioxide","C. Nitrogen","D. Hydrogen"]', 'A', 'Photolysis of water at photosystem II splits water into oxygen, protons and electrons: 2H₂O → O₂ + 4H⁺ + 4e⁻. The oxygen is released as a gas, while the protons and electrons reduce NADP and replace the electrons lost from the photosystems. Carbon dioxide is fixed later in the Calvin cycle, not released by photolysis, and hydrogen is transferred to NADP rather than released as a gas. Therefore the correct answer is A: Oxygen.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s2_002', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a eukaryotic cell carrying out aerobic respiration, where is most of the ATP produced?', 'multiple_choice', NULL, '["A. In the cytoplasm during glycolysis","B. At ATP synthase enzymes on the inner mitochondrial membrane during oxidative phosphorylation","C. In the mitochondrial matrix during the Krebs cycle","D. On the outer mitochondrial membrane"]', 'B', 'The bulk of ATP — around 30 or more molecules per glucose — comes from oxidative phosphorylation: the electron transport chain pumps protons across the inner mitochondrial membrane and the resulting chemiosmotic gradient drives ATP synthase on the cristae. Glycolysis in the cytoplasm nets only 2 ATP, and the Krebs cycle in the matrix yields little ATP directly; its main job is producing reduced NAD and reduced FAD to feed the electron transport chain. The outer membrane plays no part in ATP synthesis. Therefore the correct answer is B: At ATP synthase enzymes on the inner mitochondrial membrane during oxidative phosphorylation.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s2_003', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the Calvin cycle, which molecule directly supplies the hydrogen that reduces glycerate-3-phosphate (GP) to triose phosphate (TP)?', 'multiple_choice', NULL, '["A. ATP","B. Reduced NAD","C. Reduced NADP","D. Reduced FAD"]', 'C', 'The reduction of GP to TP uses reduced NADP (NADPH) as the reducing agent, with ATP supplying the energy for the reaction — both are products of the light-dependent reactions. ATP carries energy but no hydrogen, so it cannot reduce GP. NAD and FAD are the hydrogen carriers of respiration, not photosynthesis; the chloroplast light reactions reduce NADP, not NAD. Therefore the correct answer is C: Reduced NADP.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_479_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_479_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_479_guard;
INSERT INTO _migration_479_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_479_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_479_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_479_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_479_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_479_guard;
INSERT INTO _migration_479_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_479_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 3 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_479_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 3 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_479_expected e ON e.id = q.id) = 3 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_479_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
